parameters.text:
=Extract all pricing plans from the following competitor pricing page text.
Competitor: {{ $('Build Competitor List').item.json.name }}
For each plan return: name, numeric price (null if custom/contact sales), currency, billing period, and a list of features. If the page has monthly and annual prices, use the monthly price. If the page text is empty or contains no pricing, return an empty plans array.

Page text:
{{ $json.html }}

parameters.jsCode:
const extracted = $('Extract Pricing Plans').item.json.output || {};
const competitor = $('Build Competitor List').item.json.name;
const currentPlans = Array.isArray(extracted.plans) ? extracted.plans : [];
const baseline = Array.isArray($json.baseline) ? $json.baseline : [];

const norm = (s) => String(s == null ? "" : s).trim().toLowerCase();
const toNum = (v) => {
  if (v == null) return null;
  const n = parseFloat(String(v).replace(/[^0-9.]/g, ""));
  return isNaN(n) ? null : n;
};

// If the scrape or extraction failed, don't report every baseline plan as "removed".
if (currentPlans.length === 0) {
  return { json: { competitor, hasChanges: false, changeCount: 0, changes: [], currentPlanCount: 0,
    baselinePlanCount: baseline.length, currentPlans, skipped: 'No plans extracted (fetch or extraction failed)' } };
}

// index baseline by plan name
const baseByName = {};
for (const b of baseline) {
  const key = norm(b.plan_name || b.name || b.plan);
  baseByName[key] = b;
}
const curByName = {};
for (const p of currentPlans) curByName[norm(p.name)] = p;

const changes = [];

// price changes + new plans
for (const p of currentPlans) {
  const key = norm(p.name);
  const b = baseByName[key];
  const curPrice = toNum(p.price);
  if (!b) {
    changes.push({ type: 'new_plan', plan: p.name, detail: `New plan "${p.name}" at ${curPrice == null ? 'custom pricing' : curPrice}` });
    continue;
  }
  const basePrice = toNum(b.price);
  if (curPrice != null && basePrice != null && curPrice !== basePrice) {
    const dir = curPrice > basePrice ? 'increase' : 'decrease';
    const pct = basePrice === 0 ? null : Math.round(((curPrice - basePrice) / basePrice) * 1000) / 10;
    changes.push({ type: 'price_' + dir, plan: p.name, from: basePrice, to: curPrice, pctChange: pct, detail: `${p.name}: ${basePrice} -> ${curPrice}${pct == null ? '' : ' (' + (pct > 0 ? '+' : '') + pct + '%)'}` });
  }
}

// removed plans
for (const b of baseline) {
  const key = norm(b.plan_name || b.name || b.plan);
  if (!curByName[key]) {
    changes.push({ type: 'removed_plan', plan: b.plan_name || b.name || b.plan, detail: `Plan "${b.plan_name || b.name || b.plan}" no longer listed` });
  }
}

return {
  json: {
    competitor,
    hasChanges: changes.length > 0,
    changeCount: changes.length,
    changes,
    currentPlanCount: currentPlans.length,
    baselinePlanCount: baseline.length,
    currentPlans,
  },
};

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0 && r.hasChanges);

if (rows.length === 0) return [];

const today = $now.toFormat('yyyy-LL-dd');
const lines = [];
const slackLines = [];
for (const r of rows) {
  lines.push(`\n=== ${r.competitor} (${r.changeCount} change(s)) ===`);
  slackLines.push(`*${r.competitor}* — ${r.changeCount} change(s)`);
  for (const c of r.changes) {
    lines.push(`  • [${c.type}] ${c.detail}`);
    slackLines.push(`   • [${c.type}] ${c.detail}`);
  }
}

const totalChanges = rows.reduce((s, r) => s + r.changeCount, 0);
const subject = `Competitive Pricing Alert — ${rows.length} competitor(s), ${totalChanges} change(s) [${today}]`;

const reportText = `Competitive Intelligence — Pricing Positioning Report\nDate: ${today}\nCompetitors with changes: ${rows.length}\nTotal changes: ${totalChanges}\n${lines.join('\n')}`;
const slackText = `:mag: *Competitive Pricing Alert* (${today})\n${rows.length} competitor(s), ${totalChanges} change(s)\n\n${slackLines.join('\n')}`;

return [{ json: { subject, reportText, slackText, competitorsChanged: rows.length, totalChanges } }];

// Turn raw HTML into compact text so the LLM sees the pricing content, not scripts and markup.
const raw = typeof $json.html === 'string' ? $json.html : '';
const text = raw
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<(script|style|noscript|svg|head|iframe)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/(p|div|li|tr|h[1-6]|section|article|br)>/gi, '\n')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&#36;|&dollar;/g, '$')
  .replace(/&euro;/g, '€')
  .replace(/&pound;/g, '£')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

return {
  json: {
    competitor: $('Build Competitor List').item.json.name,
    url: $('Build Competitor List').item.json.url,
    fetchError: $json.error ? String($json.error.message || $json.error) : null,
    html: text.slice(0, 40000),
  },
};
